    sus1337_int = int(sus1337)
    print(f"As integer: {sus1337_int}")

    # Convert to hex
    sus1337_hex = hex(sus1337_int)[2:]  # Remove '0x' prefix
    print(f"As hex: {sus1337_hex}")

    # Try to decode hex to ASCII
    try:
        # If odd length, pad with leading zero
        if len(sus1337_hex) % 2 == 1:
            sus1337_hex = '0' + sus1337_hex

        hex_bytes = binascii.unhexlify(sus1337_hex)
        print(f"Hex to bytes: {hex_bytes}")

        try:
            decoded = hex_bytes.decode('utf-8', errors='replace')
            print(f"As UTF-8: {decoded}")
        except:
            print("Failed to decode as UTF-8")

        try:
            decoded = hex_bytes.decode('ascii', errors='replace')
            print(f"As ASCII: {decoded}")
        except:
            print("Failed to decode as ASCII")
    except binascii.Error as e:
        print(f"Error decoding hex: {e}")

